#!/usr/bin/env bash
#
# a talkback — turn the TalkBack screen reader on, off, or flip it.
#
# AI DISCLOSURE: This script was entirely generated by an AI tool
set -uo pipefail
source "$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)/lib/common.sh"
source "$A_LIB/device.sh"

TALKBACK_PACKAGE="com.google.android.marvin.talkback"
TALKBACK_SERVICE="$TALKBACK_PACKAGE/com.google.android.marvin.talkback.TalkBackService"
MAESTRO_DRIVER_PACKAGES=(dev.mobile.maestro.test dev.mobile.maestro)

ui_automation_connected() {
  "${ADB[@]}" shell dumpsys accessibility 2>/dev/null | grep -q "Ui Automation\["
}

talkback_running() {
  "${ADB[@]}" shell dumpsys accessibility 2>/dev/null | grep -q "touchExplorationEnabled=true"
}

release_ui_automation() {
  ui_automation_connected || return 0
  warn "A UI automation client is blocking accessibility services, stopping the Maestro driver"
  local pkg
  for pkg in "${MAESTRO_DRIVER_PACKAGES[@]}"; do
    "${ADB[@]}" shell am force-stop "$pkg" >/dev/null 2>&1
  done
}

wait_for_talkback() {
  local i
  for (( i = 0; i < 20; i++ )); do
    talkback_running && return 0
    sleep 0.25
  done
  return 1
}

usage() {
  cat <<USAGE
a talkback [toggle|on|off]

  toggle  flip whatever state it is in now
  on      enable the TalkBack screen reader
  off     disable all accessibility services

Runs interactively when no argument is given.
USAGE
}

arg="${1:-}"
case "$arg" in
  -h|--help|help) usage; exit 0 ;;
esac

if [[ -z "$arg" ]]; then
  pick "TalkBack" \
    "toggle|flip the current state" \
    "on|enable the screen reader" \
    "off|disable accessibility services"
  arg="$PICK_RESULT"
fi

case "$arg" in
  toggle|on|off) ;;
  *) log "a talkback: expected 'toggle', 'on' or 'off', got '$arg'"; usage >&2; exit 1 ;;
esac

resolve_device
banner "TALKBACK" "a talkback $arg" "$DEVICE_LABEL"

action="$arg"
if [[ "$action" == "toggle" ]]; then
  current="$("${ADB[@]}" shell settings get secure enabled_accessibility_services 2>/dev/null | tr -d '\r\n')"
  if [[ "$current" == *"$TALKBACK_PACKAGE"* ]]; then
    action="off"
  else
    action="on"
  fi
fi

# TalkBack ships inside the Android Accessibility Suite, which is missing from
# AOSP and some Google APIs images. Without it the write below still succeeds and
# absolutely nothing happens, so stop rather than claim success. Only the
# enabling path cares: turning it off with nothing installed is already a no-op,
# and shoving the Play Store at someone trying to disable it would be perverse.
if [[ "$action" == "on" ]] && ! package_installed "$TALKBACK_PACKAGE"; then
  warn "TalkBack is not installed on $DEVICE_LABEL."
  if open_play_store "$TALKBACK_PACKAGE"; then
    die "Opened the Play Store listing — install Android Accessibility Suite, then rerun: a talkback $arg"
  fi
  die "No Play Store on this device either. Use a Play Store system image or a physical device."
fi

if [[ "$action" == "on" ]]; then
  release_ui_automation
  "${ADB[@]}" shell settings put secure enabled_accessibility_services null >/dev/null 2>&1
  "${ADB[@]}" shell settings put secure enabled_accessibility_services "$TALKBACK_SERVICE" \
    || die "failed to enable TalkBack"
  "${ADB[@]}" shell settings put secure accessibility_enabled 1 \
    || die "failed to enable accessibility"
  if ! wait_for_talkback; then
    if ui_automation_connected; then
      die "TalkBack is enabled but blocked by a UI automation client (Appium, uiautomator, a live Maestro session). Stop it and rerun: a talkback on"
    fi
    die "TalkBack is enabled but did not start within 5s"
  fi
else
  "${ADB[@]}" shell settings put secure enabled_accessibility_services null \
    || die "failed to disable TalkBack"
fi

ok "TalkBack turned $action"
